#include "stdlib/blas/ext/base/snannsumkbn.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/blas/base/shared.h"

/**
* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm, and storing the number of non-`NaN` elements.
*
* ## Method
*
* -   This implementation uses an "improved Kahan–Babuška algorithm", as described by Neumaier (1974).
*
* ## References
*
* -   Neumaier, Arnold. 1974. "Rounding Error Analysis of Some Methods for Summing Finite Sums." _Zeitschrift Für Angewandte Mathematik Und Mechanik_ 54 (1): 39–51. doi:[10.1002/zamm.19740540106](https://doi.org/10.1002/zamm.19740540106).
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length for `X`
* @param sum      pointer for storing the sum
* @param count    pointer for storing the number of non-NaN elements
*/
void API_SUFFIX(stdlib_strided_snannsumkbn)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX, float *sum, CBLAS_INT *count ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(stdlib_strided_snannsumkbn_ndarray)( N, X, strideX, ox, sum, count );
}

/**
* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm and alternative indexing semantics, and storing the number of non-`NaN` elements.
*
* ## Method
*
* -   This implementation uses an "improved Kahan–Babuška algorithm", as described by Neumaier (1974).
*
* ## References
*
* -   Neumaier, Arnold. 1974. "Rounding Error Analysis of Some Methods for Summing Finite Sums." _Zeitschrift Für Angewandte Mathematik Und Mechanik_ 54 (1): 39–51. doi:[10.1002/zamm.19740540106](https://doi.org/10.1002/zamm.19740540106).
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length for `X`
* @param offsetX  starting index for `X`
* @param sum      pointer for storing the sum
* @param count    pointer for storing the number of non-NaN elements
*/
void API_SUFFIX(stdlib_strided_snannsumkbn_ndarray)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, float *sum, CBLAS_INT *count ) {
	CBLAS_INT ix;
	CBLAS_INT i;
	CBLAS_INT n;
	float s;
	float v;
	float t;
	float c;
	int flg;

	if ( N <= 0 ) {
		*sum = 0.0f;
		*count = 0;
		return;
	}
	ix = offsetX;
	if ( strideX == 0 ) {
		if ( stdlib_base_is_nanf( X[ ix ] ) ) {
			*sum = 0.0f;
			*count = 0;
			return;
		}
		*sum = X[ ix ] * N;
		*count = N;
		return;
	}
	// Find the first non-NaN element...
	for ( i = 0; i < N; i++ ) {
		v = X[ ix ];
		if ( !stdlib_base_is_nanf( v ) ) {
			break;
		}
		ix += strideX;
	}
	if ( i == N ) {
		*sum = 0.0f;
		*count = 0;
		return;
	}
	n = 1;
	s = v;
	ix += strideX;
	i += 1;
	flg = 0;

	// In order to preserve the sign of zero which can be lost during compensated summation below, find the first non-zero element...
	if ( s == 0.0f ) {
		for ( ; i < N; i++ ) {
			v = X[ ix ];
			if ( !stdlib_base_is_nanf( v ) ) {
				if ( v != 0.0f ) {
					flg = 1;
					break;
				}
				s += v;
				n += 1;
			}
			ix += strideX;
		}
	} else {
		flg = 1;
	}
	c = 0.0f;
	for ( ; i < N; i++ ) {
		v = X[ ix ];
		if ( !stdlib_base_is_nanf( v ) ) {
			t = s + v;
			if ( stdlib_base_absf( s ) >= stdlib_base_absf( v ) ) {
				c += (s-t) + v;
			} else {
				c += (v-t) + s;
			}
			s = t;
			n += 1;
		}
		ix += strideX;
	}
	*sum = ( flg == 1 ) ? s+c : s;
	*count = n;
}
